const feed=JSON.parse(readFileSync(new URL("./feed.json",import.meta.url)));
test("weekday noon departure",()=>assert.deepEqual(departures(feed,"River","2025-07-04T12:00:00Z",5).map(r=>r.tripId),["D1"]));

test("Saturday 00:00 board keeps Friday's last bus and Saturday's extra",()=>{
  assert.deepEqual(departures(feed,"River","2025-07-05T00:00:00Z",30),[
    {tripId:"R7",serviceDate:"2025-07-04",departure:"2025-07-05T00:12:00.000Z"},
    {tripId:"X3",serviceDate:"2025-07-05",departure:"2025-07-05T00:19:00.000Z"},
  ]);
});

test("a window crossing midnight expands both service dates",()=>{
  assert.deepEqual(departures(feed,"River","2025-07-04T23:50:00Z",30).map(r=>r.tripId),["R7","X3"]);
});

